    /**
     * Handles deleting a ATM entity
     * @param		command ${class.getDeleteCommandAlias()}
     * @return		CompletableFuture<Void>
     */
    @DeleteMapping("/delete")    
    public CompletableFuture<Void> delete( @RequestBody(required=true) DeleteATMCommand command ) {                
    	CompletableFuture<Void> completableFuture = null;
    	try {
        	ATMService delegate = service;

        	completableFuture = delegate.delete( command );
    		LOGGER.log( Level.WARNING, "Successfully deleted ATM with key " + command.getATMId() );
        }
        catch( Throwable exc ) {
        	LOGGER.log( Level.WARNING, exc.getMessage() );
        }
        
        return completableFuture;
	}        
	
    /**
     * Handles loading a ATM using a UUID
     * @param		UUID uuid 
     * @return		ATM
     */    
    @GetMapping("/load")
    public ATM load( @RequestParam(required=true) UUID uuid ) {    	
    	ATM entity = null;

    	try {  
    		entity = service.getATM( new ATMFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load ATM using Id " + uuid );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all ATM business objects
     * @return		Set<ATM>
     */
    @GetMapping("/")
    public List<ATM> loadAll() {                
    	List<ATM> aTMList = null;
        
    	try {
            // load the ATM
            aTMList = service.getAllATM();
            
            if ( aTMList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all ATMs" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all ATMs ", exc );
        	return null;
        }

        return aTMList;
                            
    }

